"""The synthetic-action recordings for the UI's tests (A2-7 backend request B1): generated by the real routes, byte-identical twice, covering every B1 case,
and kept out of every production contract. The generator is synthetic_action_contract.py; this module is its test."""

import paths as test_paths
import json
import os
from pathlib import Path

import pytest

import test_dashboard_contract as dashboard
from dashboard_contract_pages_world import PagesGenerator
from synthetic_action_contract import A, B, B1, EXTRAS, NOTE, SA, synthetic_action_cases
from test_dashboard_contract_pages import pin_process_identity

FIXTURES = test_paths.FIXTURES
FIXTURE = FIXTURES / 'synthetic_action_contract_v1.json'
REGENERATE = 'TP_REGENERATE_SYNTHETIC_ACTION_CONTRACT'
OUTPUT = 'TP_SYNTHETIC_ACTION_CONTRACT_OUT'
PRODUCTION_FIXTURES = ('dashboard_contract_pages_v1.json', 'dashboard_contract_v1.json', 'harvest_status_v1.json')


def build(dash, base, monkeypatch):
    base = Path(base) / 'contract'
    gen = PagesGenerator(dash, base, monkeypatch)
    synthetic_action_cases(gen)
    document = dict(version=1, generated_by='backend/tests/test_synthetic_action_contract.py', test_only=True, notes={SA: NOTE}, cases={family: dict(cases) for family, cases in gen.cases.items()})
    return dashboard.alias_ids(pin_process_identity(dashboard.pin_processes(dashboard.scrub(document, base))))


def fixture():
    assert FIXTURE.exists(), f'run with {REGENERATE}=1 to publish it'
    return json.loads(FIXTURE.read_text(encoding='utf-8'))


def test_the_published_recordings_match_what_the_routes_answer_and_are_the_same_twice(dash, tmp_path, monkeypatch):
    generated = build(dash, tmp_path / 'first', monkeypatch)
    text = dashboard.render(generated)
    for leak in (str(tmp_path), str(tmp_path).replace('\\', '\\\\'), tmp_path.as_posix(), str(Path(dash.__file__).parents[1]), str(Path(dash.__file__).parents[1]).replace('\\', '\\\\')):
        assert leak not in text, 'a machine path leaked into the recordings'
    assert 'NaN' not in text and 'Infinity' not in text
    assert dashboard.render(build(dash, tmp_path / 'second', monkeypatch)) == text, 'the recordings differ between two runs'
    target = os.environ.get(OUTPUT)
    if target:
        Path(target).parent.mkdir(parents=True, exist_ok=True)
        Path(target).write_bytes(text.encode('utf-8'))
        pytest.skip(f'recordings written to {target}; the committed fixture was not compared')
    if os.environ.get(REGENERATE):
        FIXTURES.mkdir(parents=True, exist_ok=True)
        FIXTURE.write_bytes(text.encode('utf-8'))
        pytest.skip('fixture regenerated: review the diff and tell the UI author')
    assert json.loads(FIXTURE.read_text(encoding='utf-8')) == generated


def test_every_case_the_brief_asks_for_is_in_the_fixture():
    cases = fixture()['cases'][SA]
    missing = {brief: key for brief, key in B1.items() if key not in cases}
    assert not missing, f'B1 cases the fixture lacks: {missing}'
    unnamed = sorted(set(cases) - set(B1.values()) - set(EXTRAS))
    assert not unnamed, f'cases no B1 row and no declared extra names: {unnamed}'
    assert not [extra for extra in EXTRAS if extra not in cases]


def test_the_answers_are_the_ones_the_brief_describes():
    cases = fixture()['cases'][SA]
    status = {name: case['status'] for name, case in cases.items()}
    assert status['synthetic_live_field_out_of_bounds_refused'] == 400 and status['synthetic_run_now_unknown_variant_refused'] == 400
    assert status['synthetic_run_now_changed_payload_refused'] == 409 and status['synthetic_stale_generation_refused'] == 409
    assert status['synthetic_run_now_reply_unknown'] == 500 and cases['synthetic_run_now_reply_unknown']['body']['code'] == 'command_outcome_unknown'
    replay, first = cases['synthetic_run_now_replay_after_driver_ended'], cases['synthetic_run_now_accepted']
    assert status['synthetic_run_now_replay_after_driver_ended'] == 200 and replay['body']['command']['id'] == first['body']['command']['id']
    done = cases['synthetic_run_now_read_completed_unconfirmed']['body']['battle']
    item = next(entry for entry in done['runtime']['actions']['items'] if entry['key'] == A)
    command = next(entry for entry in done['commands'] if entry['id'] == first['body']['command']['id'])
    assert item['last']['effect'] == 'unconfirmed' and item['last']['command_id'] == command['id'] and command['state'] == 'completed'
    detail = cases['synthetic_battle_detail_executions']['body']['executions']['items']
    assert command['id'] in {row['command_id'] for row in detail}
    assert cases['synthetic_projection_newer_schema']['body']['battle']['runtime']['actions']['schema_version'] == 2
    active = cases['synthetic_active_two_instances']['body']['battle']
    assert {A, B} <= {entry['key'] for entry in active['runtime']['actions']['items']}


def test_the_synthetic_action_is_in_no_production_contract():
    for name in PRODUCTION_FIXTURES:
        path = FIXTURES / name
        if path.exists():
            assert 'synthetic_probe' not in path.read_text(encoding='utf-8'), f'{name} names the test-only action'
    assert FIXTURE.name not in {path.name for path in FIXTURES.glob('dashboard_contract*.json')}
